import os
from typing import Any, Dict, List, Optional, Union

import boto3


def _normalize_bbox(bbox: Dict[str, Any]) -> Dict[str, float]:
    keys = ("Left", "Top", "Width", "Height")
    return {k.lower(): float(bbox.get(k, 0.0)) for k in keys}


def _safe_get(block: Dict[str, Any], key: str, default=None):
    return block.get(key, default)


def extract_table_cells_and_rows(document: Union[str, bytes, Any]) -> Dict[str, Any]:
    """
    Extract table cells and row structure from a document using Amazon Textract.

    Args:
        document: Path to a local file, raw bytes, or a file-like object supporting read().

    Returns:
        A dictionary containing table structure, including cells grouped by rows.
    """
    textract = boto3.client("textract")

    if isinstance(document, str):
        with open(document, "rb") as f:
            file_bytes = f.read()
    elif isinstance(document, bytes):
        file_bytes = document
    elif hasattr(document, "read"):
        file_bytes = document.read()
    else:
        raise TypeError("document must be a file path, bytes, or file-like object")

    response = textract.analyze_document(
        Document={"Bytes": file_bytes},
        FeatureTypes=["TABLES"],
    )

    blocks = response.get("Blocks", [])
    block_map = {block["Id"]: block for block in blocks if "Id" in block}

    tables: List[Dict[str, Any]] = []

    for block in blocks:
        if block.get("BlockType") != "TABLE":
            continue

        table_id = block["Id"]
        cell_ids = [rel["Ids"] for rel in block.get("Relationships", []) if rel.get("Type") == "CHILD"]
        child_ids = [cid for group in cell_ids for cid in group]

        cells = [block_map[cid] for cid in child_ids if cid in block_map and block_map[cid].get("BlockType") == "CELL"]

        rows: Dict[int, List[Dict[str, Any]]] = {}
        for cell in cells:
            row_index = int(cell.get("RowIndex", 0))
            col_index = int(cell.get("ColumnIndex", 0))
            text = ""
            for rel in cell.get("Relationships", []):
                if rel.get("Type") != "CHILD":
                    continue
                for word_id in rel.get("Ids", []):
                    word = block_map.get(word_id)
                    if word and word.get("BlockType") == "WORD":
                        text = (text + " " + word.get("Text", "")).strip()

            cell_data = {
                "row_index": row_index,
                "column_index": col_index,
                "row_span": int(cell.get("RowSpan", 1)),
                "column_span": int(cell.get("ColumnSpan", 1)),
                "text": text,
                "confidence": float(cell.get("Confidence", 0.0)),
                "bbox": _normalize_bbox(cell.get("Geometry", {}).get("BoundingBox", {})),
            }
            rows.setdefault(row_index, []).append(cell_data)

        normalized_rows = []
        for row_index in sorted(rows.keys()):
            row_cells = sorted(rows[row_index], key=lambda c: c["column_index"])
            normalized_rows.append(
                {
                    "row_index": row_index,
                    "cells": row_cells,
                }
            )

        tables.append(
            {
                "table_id": table_id,
                "rows": normalized_rows,
                "cells": [
                    {
                        "row_index": int(cell.get("RowIndex", 0)),
                        "column_index": int(cell.get("ColumnIndex", 0)),
                        "row_span": int(cell.get("RowSpan", 1)),
                        "column_span": int(cell.get("ColumnSpan", 1)),
                        "text": next(
                            (
                                " ".join(
                                    block_map[word_id].get("Text", "")
                                    for rel in cell.get("Relationships", [])
                                    if rel.get("Type") == "CHILD"
                                    for word_id in rel.get("Ids", [])
                                    if word_id in block_map and block_map[word_id].get("BlockType") == "WORD"
                                ).split()
                            ),
                            "",
                        ),
                        "confidence": float(cell.get("Confidence", 0.0)),
                        "bbox": _normalize_bbox(cell.get("Geometry", {}).get("BoundingBox", {})),
                    }
                    for cell in sorted(cells, key=lambda c: (int(c.get("RowIndex", 0)), int(c.get("ColumnIndex", 0))))
                ],
            }
        )

    return {
        "provider": "amazon-textract",
        "tables": tables,
        "raw_response": response,
    }
